function node(v){ return {v:v,l:null,r:null}; }
function insert(root,v){ if(root===null) return node(v); if(v<root.v) root.l=insert(root.l,v); else if(v>root.v) root.r=insert(root.r,v); return root; }
function build(a){ var r=null; for(var i=0;i<a.length;i++) r=insert(r,a[i]); return r; }
function search(r,v){ while(r){ if(v===r.v) return true; r = v<r.v?r.l:r.r; } return false; }
function inorder(r,out){ if(!r) return; inorder(r.l,out); out.push(r.v); inorder(r.r,out); }
function minv(r){ while(r&&r.l) r=r.l; return r?r.v:null; }
function maxv(r){ while(r&&r.r) r=r.r; return r?r.v:null; }
function remove(r,v){ if(!r) return null; if(v<r.v) r.l=remove(r.l,v); else if(v>r.v) r.r=remove(r.r,v);
  else { if(!r.l) return r.r; if(!r.r) return r.l; var m=r.r; while(m.l) m=m.l; r.v=m.v; r.r=remove(r.r,r.v); } return r; }
var EXPORTS={build:build, search:search, inorder:inorder, minv:minv, maxv:maxv, remove:remove};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.BSTForgePure = EXPORTS; }
